import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";
import { prisma } from "@/lib/prisma";
import { Prisma } from "@/generated/prisma/client";
import { loadTaskFor } from "@/lib/work/access";
import { bad, logWorkActivity, notFound, notifyWork, workGuard } from "@/lib/work/server";
import { taskCode } from "@/lib/work/model";

type Ctx = { params: Promise<{ id: string }> };

const schema = z.object({
  /** Generated by the form once per report — a retry or double tap reuses it. */
  idempotencyKey: z.string().min(8).max(80),
  /** Work ADDED since the last report, per target (never a running total). */
  lines: z.array(z.object({ targetId: z.string().min(1).max(64), quantity: z.number().int().min(0).max(1_000_000) })).max(30).default([]),
  summary: z.string().trim().max(5000).optional(),
  inProgress: z.string().trim().max(5000).optional(),
  blockers: z.string().trim().max(5000).optional(),
  nextSteps: z.string().trim().max(5000).optional(),
  nextUpdateAt: z.coerce.date().optional(),
  links: z.array(z.string().trim().url().max(2000)).max(50).default([]),
  attachments: z
    .array(z.object({ key: z.string().min(1).max(300), name: z.string().max(200), size: z.number().int().min(0), type: z.string().max(100) }))
    .max(20)
    .default([]),
  /** Hand the whole task in for final review with this report. */
  isFinal: z.boolean().default(false),
});

/**
 * POST /api/admin/work/tasks/:id/reports — a progress report.
 *
 * Counted only when APPROVED (or straight away on a task that doesn't need
 * review). The idempotency key is unique in the table, so the same report can
 * never be filed — or counted — twice.
 */
export async function POST(req: NextRequest, { params }: Ctx) {
  const g = await workGuard();
  if ("error" in g) return g.error;
  const a = g.actor;
  const { id } = await params;
  const found = await loadTaskFor(a, id);
  if (!found) return notFound();
  const { task, caps } = found;
  if (!caps.report) return bad("Only people doing this task can report on it, while it is open.", 403);
  if (!found.member?.acceptedAt) return bad("Accept the task first.", 409);
  const parsed = schema.safeParse(await req.json().catch(() => null));
  if (!parsed.success) return bad(parsed.error.issues[0]?.message ?? "Invalid report");
  const b = parsed.data;

  const already = await prisma.workReport.findUnique({ where: { idempotencyKey: b.idempotencyKey }, select: { id: true, taskId: true } });
  if (already) {
    return already.taskId === id ? NextResponse.json({ ok: true, id: already.id, duplicate: true }) : bad("Invalid report key.");
  }

  const targets = await prisma.workTarget.findMany({ where: { taskId: id }, select: { id: true, assigneeId: true } });
  const lines = b.lines.filter((l) => l.quantity > 0);
  for (const l of lines) {
    const t = targets.find((x) => x.id === l.targetId);
    if (!t) return bad("A reported target doesn't belong to this task.");
    // Individual targets: report only against your own (or a shared one).
    if (t.assigneeId && t.assigneeId !== a.userId) return bad("You can only report against your own target.", 403);
  }
  if (new Set(lines.map((l) => l.targetId)).size !== lines.length) return bad("A target is listed twice.");
  if (!lines.length && !b.summary && !b.blockers) return bad("Add progress numbers or describe the work.");
  if (task.evidenceRequired && lines.length && !b.links.length && !b.attachments.length) {
    return bad("This task needs evidence — add links or files.");
  }
  for (const f of b.attachments) {
    if (!f.key.startsWith(`work-evidence/${id}/`)) return bad("Invalid attachment.");
  }

  const auto = !task.reviewRequired;
  let report;
  try {
    report = await prisma.workReport.create({
      data: {
        taskId: id,
        authorId: a.userId,
        status: auto ? "APPROVED" : "SUBMITTED",
        summary: b.summary || null,
        inProgress: b.inProgress || null,
        blockers: b.blockers || null,
        nextSteps: b.nextSteps || null,
        nextUpdateAt: b.nextUpdateAt ?? null,
        links: b.links,
        attachments: b.attachments.length ? (b.attachments as object) : undefined,
        isFinal: b.isFinal,
        idempotencyKey: b.idempotencyKey,
        ...(auto ? { reviewedAt: new Date(), reviewNote: "Counted automatically — this task needs no review." } : {}),
        lines: { create: lines.map((l) => ({ targetId: l.targetId, quantity: l.quantity })) },
      },
    });
  } catch (e) {
    if (e instanceof Prisma.PrismaClientKnownRequestError && e.code === "P2002") {
      const r = await prisma.workReport.findUnique({ where: { idempotencyKey: b.idempotencyKey }, select: { id: true } });
      return NextResponse.json({ ok: true, id: r?.id, duplicate: true });
    }
    throw e;
  }

  const next = b.isFinal ? "IN_REVIEW" : task.status === "ASSIGNED" || task.status === "CHANGES_REQUESTED" ? "IN_PROGRESS" : null;
  await prisma.workTask.update({
    where: { id },
    data: { lastReportAt: new Date(), ...(next && next !== task.status ? { status: next } : {}) },
  });
  // A report answers the update requests that were waiting on this person.
  await prisma.workRequest.updateMany({
    where: { taskId: id, toId: a.userId, kind: { in: ["UPDATE", "REMINDER"] }, status: "OPEN" },
    data: { status: "ANSWERED", answeredAt: new Date() },
  });

  const added = lines.reduce((s, l) => s + l.quantity, 0);
  await logWorkActivity({
    taskId: id,
    projectId: task.projectId,
    actorId: a.userId,
    type: "REPORT_SUBMITTED",
    summary: `${auto ? "Reported (counted)" : "Submitted a report"}${added ? ` — +${added}` : ""}${b.isFinal ? " · for final review" : ""}`,
    meta: { reportId: report.id, lines },
  });
  const reviewers = await prisma.workTaskMember.findMany({ where: { taskId: id, role: "REVIEWER" }, select: { userId: true } });
  const to = [task.createdById, task.managerId, ...reviewers.map((r) => r.userId)].filter((u): u is string => !!u && u !== a.userId);
  await notifyWork(to, {
    title: `${taskCode(task.number)}: ${auto ? "progress reported" : "report to review"}`,
    message: `${task.title}${added ? ` — +${added}` : ""}`,
    taskId: id,
  });

  return NextResponse.json({ ok: true, id: report.id, status: report.status }, { status: 201 });
}
